`toKebabIdentifier` converts an ASCII camel/Pascal identifier to lowercase kebab form. Insert a hyphen before an uppercase letter when it follows a lowercase letter or digit, or when it is the last uppercase letter immediately before a lowercase letter. Existing hyphens are preserved, consecutive uppercase runs stay grouped, and an empty string remains empty. Examples implied by the rule include `"httpServer" -> "http-server"`, `"URLValue" -> "url-value"`, `"HTML" -> "html"`, and `"item2Code" -> "item2-code"`.

`renameOwnField` mutates only the supplied object. If `oldName === newName`, do nothing. If `oldName` is not an own property, do nothing. Otherwise copy the complete property descriptor to `newName`, overwriting any existing own property there, then delete `oldName`. Symbols and inherited properties are outside the API.

`replaceMatches` delegates to JavaScript string replacement semantics without mutating inputs. `encodeScalar` returns `"null"` for null, JSON string syntax for strings, decimal text for finite numbers, and `"true"` or `"false"` for booleans; it throws `TypeError("unsupported scalar")` for every other value, including non-finite numbers and `undefined`.

Known-bad source:

```ts
export function toKebabIdentifier(value: string): string {
  return value
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .toLowerCase();
}

export function renameOwnField(
  target: Record<string, unknown>,
  oldName: string,
  newName: string,
): void {
  if (oldName === newName || !Object.prototype.hasOwnProperty.call(target, oldName)) return;
  const descriptor = Object.getOwnPropertyDescriptor(target, oldName);
  if (descriptor === undefined) return;
  Object.defineProperty(target, newName, descriptor);
  delete target[oldName];
}

export function replaceMatches(value: string, pattern: RegExp, replacement: string): string {
  return value.replace(pattern, replacement);
}

export function encodeScalar(value: string | number | boolean | null): string {
  if (value === null) return "null";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number") {
    if (!Number.isFinite(value)) throw new TypeError("unsupported scalar");
    return String(value);
  }
  if (typeof value === "boolean") return String(value);
  throw new TypeError("unsupported scalar");
}
```

