import { toKebabIdentifier, renameOwnField, replaceMatches, encodeScalar } from './solution';

function equal(actual: unknown, expected: unknown, label: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function ok(condition: boolean, label: string): void {
  if (!condition) throw new Error(label);
}

function unsupported(value: unknown, label: string): void {
  try {
    encodeScalar(value as string);
  } catch (error) {
    ok(error instanceof TypeError, `${label}: wrong error type`);
    ok((error as Error).message === 'unsupported scalar', `${label}: wrong message`);
    return;
  }
  throw new Error(`${label}: did not throw`);
}

equal([
  toKebabIdentifier(''),
  toKebabIdentifier('httpServer'),
  toKebabIdentifier('URLValue'),
  toKebabIdentifier('HTML'),
  toKebabIdentifier('item2Code'),
  toKebabIdentifier('already-kebab'),
  toKebabIdentifier('parseHTTPResponse'),
  toKebabIdentifier('ABc'),
], [
  '',
  'http-server',
  'url-value',
  'html',
  'item2-code',
  'already-kebab',
  'parse-http-response',
  'a-bc',
], 'kebab conversion rules');

const target: Record<string, unknown> = {};
let stored = 7;
Object.defineProperty(target, 'old', {
  get(): number { return stored; },
  set(value: unknown): void { stored = value as number; },
  enumerable: false,
  configurable: true,
});
Object.defineProperty(target, 'new', {
  value: 'replace me',
  writable: true,
  enumerable: true,
  configurable: true,
});
const oldDescriptor = Object.getOwnPropertyDescriptor(target, 'old');
renameOwnField(target, 'old', 'new');
ok(!Object.prototype.hasOwnProperty.call(target, 'old'), 'old own property is deleted');
ok(Object.prototype.hasOwnProperty.call(target, 'new'), 'new own property exists');
const newDescriptor = Object.getOwnPropertyDescriptor(target, 'new');
ok(newDescriptor?.get === oldDescriptor?.get, 'getter descriptor is copied');
ok(newDescriptor?.set === oldDescriptor?.set, 'setter descriptor is copied');
ok(newDescriptor?.enumerable === false && newDescriptor.configurable === true, 'descriptor flags are copied');
target.new = 11;
ok(stored === 11, 'copied setter works');

const unchanged = { same: 1 };
renameOwnField(unchanged, 'same', 'same');
equal(unchanged, { same: 1 }, 'equal names do nothing');
const inherited = Object.create({ inherited: 3 }) as Record<string, unknown>;
renameOwnField(inherited, 'inherited', 'renamed');
ok(!Object.prototype.hasOwnProperty.call(inherited, 'renamed'), 'inherited old property is ignored');

const source = 'a1 a2 a3';
const pattern = /a(\d)/g;
ok(replaceMatches(source, pattern, '[$1:$&]') === '[1:a1] [2:a2] [3:a3]', 'native replacement semantics');
ok(source === 'a1 a2 a3' && pattern.source === 'a(\\d)', 'replacement does not alter source inputs');
ok(replaceMatches('one one', /one/, 'two') === 'two one', 'non-global replacement semantics');

equal([
  encodeScalar(null),
  encodeScalar('a\n"b'),
  encodeScalar(0),
  encodeScalar(-12.5),
  encodeScalar(true),
  encodeScalar(false),
], ['null', '"a\\n\\"b"', '0', '-12.5', 'true', 'false'], 'supported scalar encoding');

for (const value of [undefined, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY, {}, [], Symbol('x'), 1n]) {
  unsupported(value, `unsupported ${typeof value}`);
}

